@SpringBootTest
@AutoConfigureMockMvc
class TmpVerifyTest {

    @Autowired
    MockMvc mockMvc;

    @Test
    void duplicate_id_is_409_and_does_not_overwrite_name() throws Exception {
        String id = "44444444-4444-4444-4444-444444444444";
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + id + "\",\"name\":\"원래이름\"}"))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + id + "\",\"name\":\"덮어쓰기\"}"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_ALREADY_EXISTS"));
        mockMvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/members/" + id))
                .andExpect(jsonPath("$.name").value("원래이름"));
    }

    @Test
    void custom_non_sponsor_id_still_limited_to_five() throws Exception {
        String id = "55555555-5555-5555-5555-555555555555";
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + id + "\",\"name\":\"일반\"}"))
