package com.example.lending;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class TmpVerifyTest {

    @Autowired
    MockMvc mockMvc;

    @Test
    void duplicate_id_is_409_and_does_not_overwrite_name() throws Exception {
        String id = "44444444-4444-4444-4444-444444444444";
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + id + "\",\"name\":\"원래이름\"}"))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + id + "\",\"name\":\"덮어쓰기\"}"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_ALREADY_EXISTS"));
        mockMvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/members/" + id))
                .andExpect(jsonPath("$.name").value("원래이름"));
    }

    @Test
    void custom_non_sponsor_id_still_limited_to_five() throws Exception {
        String id = "55555555-5555-5555-5555-555555555555";
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + id + "\",\"name\":\"일반\"}"))
                .andExpect(status().isCreated());
        for (int i = 0; i < 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanBody(bookId(), id)))
                    .andExpect(status().isCreated());
        }
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId(), id)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    String bookId() throws Exception {
        String r = mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Tmp\"}"))
                .andReturn().getResponse().getContentAsString();
        return new com.fasterxml.jackson.databind.ObjectMapper().readTree(r).get("id").asText();
    }

    String loanBody(String bookId, String memberId) {
        return "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\"}";
    }
}
